package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsEmergencyFood {
 @GameTest(template="empty") public static void privateReadyFoodPrecedesEmergencyGrants(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){
  CityTestsModel.configure(f);var artisan=f.r.state.people.values().stream().filter(p->p.role==RuralRules.Role.ARTISAN&&f.r.state.families.get(p.family).city.equals(f.village.id)).findFirst().orElseThrow();var family=f.r.state.families.get(artisan.family);var stores=f.r.stocks(family.id);for(var box:stores){box.wheat=box.bread=0;RuralMeat.clear(box);}RuralRules.put(stores,true,8);f.village.works.emergency=true;f.village.works.resources.put("minecraft:bread",10);artisan.nourishment=20;long food=f.village.works.emergencyMeals;RuralSuccession.aid(f.s,f.village,family);h.assertTrue(artisan.nourishment==20&&f.village.works.emergencyMeals==food&&f.village.works.resources.get("minecraft:bread")==10,"Existing private meals prevent a public meal grant");RuralSuccession.emergencyNow(f.s,f.village);h.assertTrue(artisan.nourishment==20,"Immediate disaster aid also respects private ready food");RuralRules.meal(RuralRules.members(family,f.r.state.people),stores);h.assertTrue(RuralRules.count(stores,true)<8,"The household consumes its real food instead of permanently bypassing it");
 }h.succeed();}
 @GameTest(template="empty") public static void emergencyFallbackCannotTakeHeadsLastReadyMeals(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){
  CityTestsModel.configure(f);var head=f.r.state.people.get(f.t.head(f.village.id).worker);var stores=f.r.stocks(head.family);for(var box:stores){box.wheat=box.bread=0;RuralMeat.clear(box);}for(var p:RuralRules.members(f.r.state.families.get(head.family),f.r.state.people))p.nourishment=p.maximum();RuralRules.put(stores,false,740);RuralRules.put(stores,true,10);f.village.works.resources.remove("minecraft:bread");long before=f.r.audit(f.village.id).breadEaten;int first=CityWorksFinance.publicMeals(f.s,f.village,20),second=CityWorksFinance.publicMeals(f.s,f.village,20);h.assertTrue(first==2&&second==0&&RuralRules.count(stores,true)==8,"Only the two genuinely spare ready portions may leave the head family");h.assertTrue(f.r.audit(f.village.id).breadEaten==before+2,"Every donated portion is recorded once");
 }h.succeed();}
 @GameTest(template="empty") public static void ordinaryWorkshopRecoveryCraftsFromFourRealPlanks(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){
  for(long p:f.house.baseline.keySet()){f.house.damaged.add(p);h.getLevel().setBlock(net.minecraft.core.BlockPos.of(p),Blocks.AIR.defaultBlockState(),3);}f.city.works.emergency=true;f.city.works.resources.put("minecraft:oak_planks",3);String payer=CityEconomy.treasury(f.city.id);h.assertTrue(!CityWorksFinance.canMaterial(f.server,f.city,f.house,Blocks.CRAFTING_TABLE.defaultBlockState(),true,payer),"Three planks cannot restore a workbench");f.city.works.resources.put("minecraft:oak_planks",5);for(int i=0;i<3;i++)h.assertTrue(CityWorksFinance.canMaterial(f.server,f.city,f.house,Blocks.CRAFTING_TABLE.defaultBlockState(),true,payer),"Preflight can find a real recipe");h.assertTrue(f.city.works.resources.get("minecraft:oak_planks")==5,"Repeated preflight cannot consume inputs");long money=f.money();CityWorks.worker(f.server,f.city,f.worker,0);CityWorks.updateEmergency(f.server,f.city);h.assertTrue(f.house.damaged.isEmpty()&&!f.city.works.emergency&&f.city.works.repaired==2,"Ordinary maintenance ends total-workshop destruction without the risk-test helper");h.assertTrue(f.city.works.resources.get("minecraft:oak_planks")==0&&f.city.works.crafted.get("minecraft:crafting_table")==1&&f.city.works.materialsConsumed.get("minecraft:oak_planks")==5&&f.city.works.materialsConsumed.get("minecraft:crafting_table")==1&&f.money()==money,"Four input planks become one consumed bench, plus one repaired plank; no currency or material creation");
 }h.succeed();}
 @GameTest(template="empty") public static void caregiverIndexMatchesPreviousRule(GameTestHelper h){var random=new Random(401104);for(int run=0;run<20;run++){
  var people=new LinkedHashMap<UUID,RuralRules.Person>();var families=List.of(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID());for(int i=0;i<100;i++){var p=new RuralRules.Person();p.id=UUID.randomUUID();p.family=families.get(random.nextInt(3));p.age=RuralRules.Age.values()[random.nextInt(6)];p.pregnant=random.nextBoolean();p.dead=random.nextInt(5)==0;p.infants=random.nextInt(3);p.nourishment=p.maximum()*random.nextDouble();people.put(p.id,p);}var ids=new ArrayList<>(people.keySet());for(var p:people.values())p.caregiver=ids.get(random.nextInt(ids.size()));var expected=new HashMap<UUID,Integer>();var nour=new HashMap<UUID,Double>();for(var p:people.values()){int count=(int)people.values().stream().filter(b->!b.dead&&b.age==RuralRules.Age.INFANT&&p.id.equals(b.caregiver)&&Objects.equals(p.family,b.family)).count();double old=p.maximum(),fraction=old<=0?1:p.nourishment/old;expected.put(p.id,count);nour.put(p.id,(p.age==RuralRules.Age.INFANT?0:(p.age==RuralRules.Age.CHILD?1:2)+(p.pregnant?1:0)+count)*15.0*fraction);}RuralRules.refreshCaregivers(people);for(var p:people.values())h.assertTrue(p.infants==expected.get(p.id)&&Math.abs(p.nourishment-nour.get(p.id))<1e-8,"Linear caregiver indexing preserves family, death and nutrition rules");
 }h.succeed();}
}
